-- Firma dışa aktarımı: tek MVCC kesiti, salt okunur. Kullanıcı SQL Editor'da çalıştırır.
BEGIN;
ALTER TABLE public.store_urunler ALTER COLUMN puan_fiyati DROP NOT NULL;
ALTER TABLE public.store_urunler ALTER COLUMN puan_fiyati DROP DEFAULT;
COMMENT ON COLUMN public.store_urunler.puan_fiyati IS 'Eski merkezî fiyat; yeni FirmaStore siparişlerinde kullanılmaz. Geçmiş uyumluluğu için korunur.';
CREATE OR REPLACE FUNCTION public.admin_firma_export_snapshot(p_firma uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $export$
DECLARE v_veri jsonb := '{}'::jsonb; v_satirlar jsonb; v_an timestamptz:=statement_timestamp();
