 IF p_firma IS NULL OR NOT EXISTS(SELECT 1 FROM public.firmalar WHERE firma_id=p_firma) THEN
 RAISE EXCEPTION 'Firma bulunamadı.' USING ERRCODE='22023'; END IF;
